corrected_code:
use Illuminate\Support\Facades\Broadcast;
use App\Models\User;

// routes/channels.php
Broadcast::channel('portfolio.{accountId}', function (User $user, int $accountId) {
    return $user->tradingAccounts()
        ->where('accounts.id', $accountId)
        ->wherePivot('is_active', true)
        ->exists();
});
